import React, { useState } from 'react';
import { Grommet, Box, Select, DataTable, Text } from 'grommet';
import { FormDown, FormUp } from 'grommet-icons';

const items = [
  { Date: '2023-01-01', Time: '08:00', Type: 'Error', Source: 'API', Partition: 'A', Severity: 'High', Level: '1', Data: 'Foo', Keyword: 'alpha', Details: 'Detail 1' },
  { Date: '2023-01-01', Time: '09:15', Type: 'Warning', Source: 'UI', Partition: 'B', Severity: 'Low', Level: '2', Data: 'Bar', Keyword: 'beta', Details: 'Detail 2' },
  { Date: '2023-01-02', Time: '10:30', Type: 'Info', Source: 'Worker', Partition: 'A', Severity: 'Medium', Level: '3', Data: 'Baz', Keyword: 'gamma', Details: 'Detail 3' },
  // add more rows as needed
];

const allColumns = [
  { property: 'Date', header: 'Date' },
  { property: 'Time', header: 'Time' },
  { property: 'Type', header: 'Type' },
  { property: 'Source', header: 'Source' },
  { property: 'Partition', header: 'Partition' },
  { property: 'Severity', header: 'Severity' },
  { property: 'Level', header: 'Level' },
  { property: 'Data', header: 'Data' },
  { property: 'Keyword', header: 'Keyword' },
  { property: 'Details', header: 'Details' },
];

const DataTableGroup = ({ options, value, onChange }) => (
  <Select
    placeholder="Group by..."
    options={options}
    value={value}
    onChange={({ option }) => onChange(option)}
    clear={{ position: 'right' }}
    icon={({ open }) => open ? <FormUp /> : <FormDown />}
    width="small"
  />
);

export const GroupableDataTableExample = () => {
  const [groupBy, setGroupBy] = useState();

  // DataTable expects groupBy as an array of property names
  const groupByProp = groupBy ? [groupBy.property] : undefined;

  return (
    <Grommet>
      <Box pad="medium" gap="small">
        <Box direction="row" align="center" gap="small">
          <Text>Group by:</Text>
          <DataTableGroup
            options={allColumns}
            value={groupBy}
            onChange={setGroupBy}
          />
        </Box>
        <DataTable
          columns={allColumns}
          data={items}
          groupBy={groupByProp}
          // optionally show group counts
          onClickRow={(event) => console.log(event)}
        />
      </Box>
    </Grommet>
  );
};
